def integer_cube_root(c: int) -> int:
    """Binary search for the integer cube root of c, no external deps needed."""
    low, high = 0, 1
    while high**3 < c:
        high *= 2
    while low < high:
        mid = (low + high + 1) // 2
        if mid**3 <= c:
            low = mid
        else:
            high = mid - 1
    return low

